import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Pessoa } from './solution.mjs';

test('cria uma pessoa com nome e idade', () => {
  const pessoa = new Pessoa('Maria', 25);
  assert.equal(pessoa.nome, 'Maria');
  assert.equal(pessoa.idade, 25);
});

test('cada instância é um objeto independente', () => {
  const ana = new Pessoa('Ana', 18);
  const bia = new Pessoa('Bia', 20);
  assert.notEqual(ana, bia);
  assert.equal(ana.nome, 'Ana');
  assert.equal(bia.idade, 20);
});

test('recusa nome vazio ou só com espaços', () => {
  assert.throws(() => new Pessoa('', 25));
  assert.throws(() => new Pessoa('   ', 25));
});

test('recusa idade que não é número', () => {
  assert.throws(() => new Pessoa('Maria', '25'));
});

solutionCode:
// O molde de toda pessoa: constructor recebe e guarda nome e idade.
export class Pessoa {
  constructor(nome, idade) {
    // Portaria de entrada: nome precisa ser texto não vazio.
    if (typeof nome !== 'string' || nome.trim() === '') {
      throw new Error('nome precisa ser um texto não vazio');
    }
    // Idade precisa ser número — comparação de idade com texto não faz sentido.
    if (typeof idade !== 'number') {
      throw new Error('idade precisa ser um número');
    }
    // Guarda os valores nos campos da instância que está nascendo.
    this.nome = nome;
    this.idade = idade;
  }
}
